questionvariables.text:
/* Design: match loci in words to construction language, one dropdown per row. Each category appears in at least two positions. Source: original. */
sel: [[10,7,6,3],[2,6,10,7],[10,7,2,3],[3,6,2,10],[2,6,3,7],[5,4,9,8],[1,5,9,8],[4,8,9,1],[9,4,1,5],[5,8,1,4]];
ix: 1+rand(10);
s: sel[ix];
ds: ["A water kiosk is to be built the same distance from school A as from school B.","A referee moves so that she is always as far from corner flag A as from corner flag B.","A boda boda rider goes round a roundabout, always 12 m from its centre A.","A learner marks points on the field exactly 20 m from the flagpole at A.","A painter marks points 1.5 m from the straight edge l of a running track, on both sides of it.","A tractor drives so that it is always 3 m from the straight fence l, on either side.","A sprinkler is moved so that it stays the same distance from two straight hedges that meet at a corner.","A footpath is made of the points that are the same distance from two straight roads that cross.","A photographer moves so that gateposts A and B always appear \\(40^\\circ\\) apart in her view.","A surveyor stands at points where the ends A and B of a straight wall are seen at an angle of \\(30^\\circ\\)."];
keys: ["pb","circ","par","ang","arc"];
twin: ["ang","par","circ","pb","circ"];
catk(n) := keys[floor((n+1)/2)];
twk(n) := twin[floor((n+1)/2)];
mko(kv) := [["pb",is(kv="pb"),"the perpendicular bisector of AB"],["circ",is(kv="circ"),"a circle with centre A"],["par",is(kv="par"),"a pair of lines parallel to l"],["ang",is(kv="ang"),"the bisectors of the angles between the lines"],["arc",is(kv="arc"),"arcs of circles through A and B"]];
ta1: catk(s[1]); tw1: twk(s[1]); wk1: first(sublist(keys, lambda([z], is(z#ta1) and is(z#tw1)))); o1: mko(ta1);
ta2: catk(s[2]); tw2: twk(s[2]); wk2: first(sublist(keys, lambda([z], is(z#ta2) and is(z#tw2)))); o2: mko(ta2);
ta3: catk(s[3]); tw3: twk(s[3]); wk3: first(sublist(keys, lambda([z], is(z#ta3) and is(z#tw3)))); o3: mko(ta3);
ta4: catk(s[4]); tw4: twk(s[4]); wk4: first(sublist(keys, lambda([z], is(z#ta4) and is(z#tw4)))); o4: mko(ta4);
